layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU;
    void main(){
      float u = uTime - aT; if (u < 0. || u > 0.45){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = .5; vP = position.xy*.9; vU = u;                  // only the immediate base of the feet
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float seg(vec2 p, vec2 a, vec2 b){ vec2 pa = p-a, ba = b-a; float h = clamp(dot(pa,ba)/dot(ba,ba), 0., 1.); return length(pa - ba*h); }
    void main(){
      vec2 p = vP; float r = length(p);
      float k = 1. - pow(1. - clamp(vU/.06, 0., 1.), 3.);               // snaps shut in 60 ms
      float R = mix(.75, .42, k);
      float ring = 0., hot = 0.;                                        // no circle: only the stakes at the ankles (Root ≠ danger area)
      float st = 0.;
      for (int j=0;j<4;j++){
        float an = .7854 + float(j)*1.5708; vec2 d = vec2(cos(an), sin(an));
        float ds = seg(p, d*(R - .17), d*(R + .03));
        st += exp(-pow(ds/.014, 2.)); hot += lcore(ds, .004);
      }
      float f = vU < .06 ? 1. : 1. - smoothstep(.2, 0.45, vU);
      float pk = vU >= .06 && vU < .093 ? 1.6 : 1.;                    // 2-frame peak when it locks
      float edge = smoothstep(.9, .78, r);
      vec3 outc = (mix(uOrange, uGold, .6)*(ring*.9 + st*.8) + vec3(1., .95, .86)*hot*.6)*f*pk*edge;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

layers.vertex:
attribute vec3 aO, aV; attribute vec2 aT; uniform float uTime, uW; uniform vec2 uRes; varying float vF; varying vec2 vQ;
    vec3 sim(float t){ float k = 5., e = exp(-k*t); vec3 p = aO + aV*(1.-e)/k; p.y += 4.*((1.-e)/(k*k) - t/k); return p; }
    void main(){
      float age = uTime - aT.x; if (age < 0. || age > aT.y){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 ch = projectionMatrix*viewMatrix*vec4(sim(age),1.), ct = projectionMatrix*viewMatrix*vec4(sim(max(age-.03,0.)),1.);
      vec2 d = (ch.xy/ch.w - ct.xy/ct.w)*uRes; float L = length(d); vec2 dir = L > .5 ? d/L : vec2(1.,0.), nrm = vec2(-dir.y, dir.x);
      float s = position.y + .5; vec4 c = mix(ct, ch, s);
      c.xy += (nrm*position.x*uW*2. + dir*(s-.5)*uW)*2./uRes*c.w;
      gl_Position = c; vF = 1. - age/aT.y; vQ = vec2(position.x*2., s);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vF; varying vec2 vQ;
    void main(){ float a = exp(-vQ.x*vQ.x*3.)*vQ.y, c = exp(-vQ.x*vQ.x*14.)*vQ.y;
      gl_FragColor = vec4((mix(uOrange, uGold, vF)*a*1.3 + vec3(1., .95, .85)*c*vF)*(.4 + 1.3*vF*vF), 1.); }
